     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.util.Map;
     6	
     7	public class CorporatePlanStrategy implements RatePlanStrategy {
     8	    private static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
     9	        "TECNOSUL", BigDecimal.valueOf(0.12),
    10	        "AGROVALE", BigDecimal.valueOf(0.18),
    11	        "FARMAVIDA", BigDecimal.valueOf(0.25)
    12	    );
    13	
    14	    private String companyCode;
    15	
    16	    public CorporatePlanStrategy(String companyCode) {
    17	        this.companyCode = companyCode;
    18	    }
    19	
    20	    @Override
    21	    public void validate(LocalDate checkIn, LocalDate checkOut, int guests, int roomCapacity, String companyCode) {
    22	        if (companyCode == null || companyCode.isEmpty() || !COMPANY_DISCOUNTS.containsKey(companyCode)) {
    23	            throw new IllegalArgumentException("Invalid company code");
    24	        }
    25	        if (guests < 1) {
    26	            throw new IllegalArgumentException("Must have at least 1 guest");
    27	        }
    28	        if (guests > roomCapacity) {
    29	            throw new IllegalArgumentException("Guests exceed room capacity");
    30	        }
    31	        if (!checkOut.isAfter(checkIn)) {
    32	            throw new IllegalArgumentException("Check-out must be after check-in");
    33	        }
    34	    }
    35	
    36	    @Override
    37	    public PriceCalculation calculatePrice(LocalDate checkIn, LocalDate checkOut, BigDecimal baseNightlyRate, int guests) {
    38	        int nights = PricingUtils.countNights(checkIn, checkOut);
    39	        BigDecimal subtotal = BigDecimal.ZERO;
    40	
    41	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    42	            BigDecimal nightlyRate = PricingUtils.getNightlyRate(baseNightlyRate, date);
    43	            subtotal = subtotal.add(nightlyRate);
    44	        }
    45	
    46	        subtotal = PricingUtils.roundBanker(subtotal);
    47	        BigDecimal discountRate = COMPANY_DISCOUNTS.getOrDefault(companyCode, BigDecimal.ZERO);
    48	        BigDecimal discount = PricingUtils.roundBanker(subtotal.multiply(discountRate));
    49	        BigDecimal total = subtotal.subtract(discount);
    50	
    51	        return new PriceCalculation(nights, subtotal, discount, total);
    52	    }
    53	
    54	    @Override
    55	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    56	        return amountPaid;
    57	    }
    58	}
