=== pricing/PricingUtils.java
     1	package com.pousadamareaita.pricing;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PricingUtils {
     9	    public static BigDecimal roundBanker(BigDecimal value) {
    10	        return value.setScale(2, RoundingMode.HALF_EVEN);
    11	    }
    12	
    13	    public static boolean isHighSeason(LocalDate date) {
    14	        int month = date.getMonthValue();
    15	        int dayOfMonth = date.getDayOfMonth();
    16	
    17	        if (month == 7) {
    18	            return true;
    19	        }
    20	
    21	        if (month == 12) {
    22	            return dayOfMonth >= 15;
    23	        }
    24	
    25	        if (month == 1 || month == 2) {
    26	            return true;
    27	        }
    28	
    29	        return false;
    30	    }
    31	
    32	    public static BigDecimal getNightlyRate(BigDecimal baseRate, LocalDate date) {
    33	        if (isHighSeason(date)) {
    34	            return roundBanker(baseRate.multiply(BigDecimal.valueOf(1.20)));
    35	        }
    36	        return baseRate;
    37	    }
    38	
    39	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
    40	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    41	    }
    42	}
