     9	public class WeekendPackagePlanStrategy implements RatePlanStrategy {
    10	    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
    11	        RoomType.STANDARD, BigDecimal.valueOf(520.00),
    12	        RoomType.DELUXE, BigDecimal.valueOf(820.00),
    13	        RoomType.SUITE, BigDecimal.valueOf(1200.00)
    14	    );
    15	
    16	    private final RoomType roomType;
    17	
    18	    public WeekendPackagePlanStrategy(RoomType roomType) {
    19	        this.roomType = roomType;
    20	    }
    21	
    22	    @Override
    23	    public void validate(LocalDate checkIn, LocalDate checkOut, int guests, int roomCapacity, String companyCode) {
    24	        if (!checkIn.getDayOfWeek().equals(DayOfWeek.FRIDAY)) {
    25	            throw new IllegalArgumentException("Check-in must be on Friday");
    26	        }
    27	        if (!checkOut.getDayOfWeek().equals(DayOfWeek.SUNDAY)) {
    28	            throw new IllegalArgumentException("Check-out must be on Sunday");
    29	        }
    30	        int nights = PricingUtils.countNights(checkIn, checkOut);
    31	        if (nights != 2) {
    32	            throw new IllegalArgumentException("Weekend package must be exactly 2 nights");
    33	        }
    34	        if (guests < 1) {
    35	            throw new IllegalArgumentException("Must have at least 1 guest");
    36	        }
    37	        if (guests > roomCapacity) {
    38	            throw new IllegalArgumentException("Guests exceed room capacity");
    39	        }
    40	    }
    41	
    42	    @Override
    43	    public PriceCalculation calculatePrice(LocalDate checkIn, LocalDate checkOut, BigDecimal baseNightlyRate, int guests) {
    44	        int nights = 2;
    45	        BigDecimal packagePrice = PACKAGE_PRICES.get(roomType);
    46	        BigDecimal subtotal = packagePrice;
    47	        BigDecimal discount = BigDecimal.ZERO;
    48	        BigDecimal total = packagePrice;
    49	
    50	        return new PriceCalculation(nights, subtotal, discount, total);
    51	    }
    52	
    53	    @Override
    54	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    55	        return PricingUtils.roundBanker(amountPaid.multiply(BigDecimal.valueOf(0.5)));
    56	    }
    57	}
