     1	package com.pousadamareaita.service;
     2	
     3	import com.pousadamareaita.exception.*;
     4	import com.pousadamareaita.model.*;
     5	import com.pousadamareaita.pricing.*;
     6	import com.pousadamareaita.storage.*;
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	
    10	public class ReservationService {
    11	    private final ReservationRepository reservationRepository;
    12	    private final RoomRepository roomRepository;
    13	    private final MessageRepository messageRepository;
    14	
    15	    public ReservationService(ReservationRepository reservationRepository,
    16	                              RoomRepository roomRepository,
    17	                              MessageRepository messageRepository) {
    18	        this.reservationRepository = reservationRepository;
    19	        this.roomRepository = roomRepository;
    20	        this.messageRepository = messageRepository;
    21	    }
    22	
    23	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    24	                                         LocalDate checkIn, LocalDate checkOut, int guests,
    25	                                         RatePlan ratePlan, String companyCode) {
    26	        Room room = roomRepository.findByNumber(roomNumber);
    27	        if (room == null) {
    28	            throw new RoomNotFoundException(roomNumber);
    29	        }
    30	
    31	        RatePlanStrategy strategy = RatePlanStrategyFactory.create(ratePlan, room.getType(), companyCode);
    32	
    33	        try {
    34	            strategy.validate(checkIn, checkOut, guests, room.getCapacity(), companyCode);
    35	        } catch (IllegalArgumentException e) {
    36	            throw new InvalidRequestException(e.getMessage());
    37	        }
    38	
    39	        checkRoomAvailability(roomNumber, checkIn, checkOut);
    40	
    41	        PriceCalculation priceCalc = strategy.calculatePrice(checkIn, checkOut, room.getNightlyRate(), guests);
    42	
    43	        int reservationId = reservationRepository.getNextId();
    44	        Reservation reservation = new Reservation(
    45	            reservationId,
    46	            roomNumber,
    47	            guestName,
    48	            guestEmail,
    49	            guestCpf,
    50	            checkIn,
    51	            checkOut,
    52	            guests,
    53	            ratePlan,
    54	            companyCode,
    55	            priceCalc.getNights(),
    56	            priceCalc.getSubtotal(),
    57	            priceCalc.getDiscount(),
    58	            priceCalc.getTotal()
    59	        );
    60	
    61	        return reservationRepository.save(reservation);
    62	    }
    63	
    64	    public Reservation getReservation(int id) {
    65	        Reservation reservation = reservationRepository.findById(id);
    66	        if (reservation == null) {
    67	            throw new ReservationNotFoundException(id);
    68	        }
    69	        return reservation;
    70	    }
    71	
    72	    public Reservation confirmReservation(int id, BigDecimal amountPaid) {
    73	        Reservation reservation = getReservation(id);
    74	
    75	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    76	            throw new OperationNotAllowedException("Can only confirm a pending reservation");
    77	        }
    78	
    79	        reservation.confirm(amountPaid);
    80	        sendConfirmationEmail(reservation);
    81	        return reservationRepository.save(reservation);
    82	    }
    83	
    84	    public Reservation checkIn(int id) {
    85	        Reservation reservation = getReservation(id);
    86	
    87	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
    88	            throw new OperationNotAllowedException("Can only check in a confirmed reservation");
    89	        }
    90	
    91	        reservation.checkIn();
    92	        return reservationRepository.save(reservation);
    93	    }
    94	
    95	    public Reservation checkOut(int id) {
    96	        Reservation reservation = getReservation(id);
    97	
    98	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
    99	            throw new OperationNotAllowedException("Can only check out a checked-in reservation");
   100	        }
   101	
   102	        reservation.checkOut();
   103	        return reservationRepository.save(reservation);
   104	    }
   105	
   106	    public Reservation cancelReservation(int id) {
   107	        Reservation reservation = getReservation(id);
   108	
   109	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   110	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   111	            throw new OperationNotAllowedException("Can only cancel a pending or confirmed reservation");
   112	        }
   113	
   114	        RatePlanStrategy strategy = RatePlanStrategyFactory.create(
   115	            reservation.getRatePlan(),
   116	            getRoomType(reservation.getRoomNumber()),
   117	            reservation.getCompanyCode()
   118	        );
   119	
   120	        BigDecimal refund = strategy.calculateRefund(reservation.getAmountPaid());
   121	        reservation.cancel(refund);
   122	        return reservationRepository.save(reservation);
   123	    }
   124	
   125	    private void checkRoomAvailability(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   126	        for (Reservation res : reservationRepository.findAll()) {
   127	            if (res.getRoomNumber() != roomNumber) {
   128	                continue;
   129	            }
   130	
   131	            if (res.getStatus() == ReservationStatus.CANCELLED) {
   132	                continue;
   133	            }
   134	
   135	            // Overlap if: checkIn < res.getCheckOut() AND checkOut > res.getCheckIn()
