   150	    private void sendConfirmationEmail(Reservation reservation) {
   151	        String subject = "Reserva confirmada - Pousada Maré Alta";
   152	        String receipt = generateReceipt(reservation);
   153	        String body = "Olá, " + reservation.getGuestName() + "!\n\n" +
   154	                      "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   155	                      receipt + "\n\n" +
   156	                      "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   157	                      "Até breve!";
   158	
   159	        Message message = new Message(
   160	            messageRepository.getNextId(),
   161	            "EMAIL",
   162	            reservation.getGuestEmail(),
   163	            subject,
   164	            body
   165	        );
   166	        messageRepository.save(message);
   167	    }
   168	
   169	    public String generateReceipt(Reservation reservation) {
   170	        Room room = roomRepository.findByNumber(reservation.getRoomNumber());
   171	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
   172	
   173	        StringBuilder sb = new StringBuilder();
   174	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
   175	        sb.append("Hóspede: ").append(reservation.getGuestName()).append(" (CPF ").append(reservation.getGuestCpf()).append(")\n");
   176	        sb.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(room.getType()).append(")\n");
   177	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn())).append(" | ");
   178	        sb.append("Saída: ").append(formatDate(reservation.getCheckOut())).append(" | ");
   179	        sb.append(nightsText).append("\n");
   180	        sb.append("Diárias: ").append(formatCurrency(reservation.getSubtotal())).append("\n");
   181	
   182	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   183	            sb.append("Desconto: ").append(formatCurrency(reservation.getDiscount())).append("\n");
   184	        }
   185	
   186	        sb.append("Total: ").append(formatCurrency(reservation.getTotal()));
   187	
   188	        return sb.toString();
   189	    }
   190	
   191	    private String formatDate(LocalDate date) {
   192	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
   193	    }
   194	
   195	    private String formatCurrency(BigDecimal amount) {
   196	        return String.format("R$ %,.2f", amount).replace(",", ".");
   197	    }
   198	}

