    13	public class ReportService {
    14	    private final ReservationRepository reservationRepository;
    15	    private final RoomRepository roomRepository;
    16	
    17	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    18	        this.reservationRepository = reservationRepository;
    19	        this.roomRepository = roomRepository;
    20	    }
    21	
    22	    public String generateOccupancyReport(LocalDate date) {
    23	        StringBuilder csv = new StringBuilder();
    24	        csv.append("room,type,reservation,check_in,check_out\n");
    25	
    26	        List<Room> allRooms = new ArrayList<>(roomRepository.findAll());
    27	        allRooms.sort((r1, r2) -> Integer.compare(r1.getNumber(), r2.getNumber()));
    28	
    29	        int occupiedCount = 0;
    30	        for (Room room : allRooms) {
    31	            for (Reservation res : reservationRepository.findAll()) {
    32	                if (res.getRoomNumber() != room.getNumber()) {
    33	                    continue;
    34	                }
    35	                if (res.getStatus() == ReservationStatus.CANCELLED) {
    36	                    continue;
    37	                }
    38	                if (res.getStatus() != ReservationStatus.CONFIRMED &&
    39	                    res.getStatus() != ReservationStatus.CHECKED_IN &&
    40	                    res.getStatus() != ReservationStatus.CHECKED_OUT) {
    41	                    continue;
    42	                }
    43	
    44	                // Room is occupied on 'date' if: checkIn <= date < checkOut
    45	                if (!res.getCheckIn().isAfter(date) && res.getCheckOut().isAfter(date)) {
    46	                    csv.append(room.getNumber()).append(",");
    47	                    csv.append(room.getType()).append(",");
    48	                    csv.append(res.getId()).append(",");
    49	                    csv.append(formatDate(res.getCheckIn())).append(",");
    50	                    csv.append(formatDate(res.getCheckOut())).append("\n");
    51	                    occupiedCount++;
    52	                }
    53	            }
    54	        }
    55	
    56	        csv.append("total,").append(occupiedCount).append("/5\n");
    57	        return csv.toString();
    58	    }
    59	
    60	    public String generateRevenueReport(YearMonth month) {
    61	        StringBuilder csv = new StringBuilder();
    62	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    63	
    64	        List<Reservation> reservations = new ArrayList<>(reservationRepository.findAll());
    65	        reservations.sort((r1, r2) -> {
    66	            int dateComp = r1.getCheckIn().compareTo(r2.getCheckIn());
    67	            if (dateComp != 0) return dateComp;
    68	            return Integer.compare(r1.getId(), r2.getId());
    69	        });
    70	
    71	        BigDecimal totalAmount = BigDecimal.ZERO;
    72	
    73	        for (Reservation res : reservations) {
    74	            // Only include reservations that start in this month
    75	            if (!YearMonth.from(res.getCheckIn()).equals(month)) {
    76	                continue;
    77	            }
    78	
    79	            // Only include reservations that generated money or will generate money
    80	            if (res.getStatus() == ReservationStatus.PENDING || res.getStatus() == ReservationStatus.CANCELLED) {
    81	                if (res.getStatus() == ReservationStatus.CANCELLED && res.getAmountPaid().compareTo(BigDecimal.ZERO) == 0) {
    82	                    // Cancelled without payment, no money involved
    83	                    continue;
    84	                }
    85	            }
    86	
    87	            // Calculate net amount (paid - refunded)
    88	            BigDecimal netAmount = res.getAmountPaid();
    89	            if (res.getRefund() != null) {
    90	                netAmount = netAmount.subtract(res.getRefund());
    91	            }
    92	
    93	            if (netAmount.compareTo(BigDecimal.ZERO) > 0 || res.getStatus() != ReservationStatus.CANCELLED) {
    94	                csv.append(res.getId()).append(",");
    95	                csv.append(res.getRoomNumber()).append(",");
    96	                csv.append(formatDate(res.getCheckIn())).append(",");
    97	                csv.append(formatDate(res.getCheckOut())).append(",");
    98	                csv.append(res.getStatus()).append(",");
    99	                csv.append(formatCurrencyForCSV(res.getAmountPaid())).append("\n");
   100	                totalAmount = totalAmount.add(netAmount);
   101	            }
   102	        }
   103	
   104	        csv.append("total,,,,").append(formatCurrencyForCSV(totalAmount)).append("\n");
   105	        return csv.toString();
   106	    }
   107	
   108	    private String formatDate(LocalDate date) {
   109	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
   110	    }
   111	
   112	    private String formatCurrencyForCSV(BigDecimal amount) {
   113	        return String.format("%.2f", amount);
   114	    }
   115	}
